python << 'EOF'
import json

with open(r"C:\Users\win\.codex\.codex-global-state.json", "r", encoding="utf-8") as f:
    data = json.load(f)

# 查找所有线程
threads = []
for key, value in data.items():
    if isinstance(value, list):
        for item in value:
            if isinstance(item, dict) and "id" in item and "title" in item:
                threads.append({
                    "id": item.get("id"),
                    "title": item.get("title", "N/A"),
                    "path": item.get("projectPath", "N/A"),
                    "created": item.get("createdAt", "N/A")
                })

# 过滤与当前项目相关的线程
project_path = r"C:\Users\win\Desktop\AI--main"
relevant = [t for t in threads if project_path in str(t.get("path", ""))]

print(f"找到 {len(threads)} 个线程，其中 {len(relevant)} 个与当前项目相关\n")

if relevant:
    print("最近的5个相关线程:")
    for t in relevant[-5:]:
        print(f"  ID: {t['id']}")
        print(f"  标题: {t['title'][:80]}")
        print(f"  创建: {t['created']}")
        print()
else:
    print("没有找到与当前项目相关的线程")
EOF
